private string ResolveSpData(string viewType)
{
    string strView = NormalizeViewType(viewType);
    if (strView == "reward")
        return SP_REWARD;
    return SP_SANCTION;
}

private string NormalizeViewType(string viewType)
{
    if (viewType == null)
        return "sanction";

    string strView = viewType.Trim().ToLower();
    if (strView == "reward")
        return "reward";
    return "sanction";
}

